package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.*;import net.minecraft.core.*;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.phys.*;import net.neoforged.neoforge.client.event.*;import net.neoforged.bus.api.SubscribeEvent;import com.mojang.math.Axis;
@net.neoforged.fml.common.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID,value=net.neoforged.api.distmarker.Dist.CLIENT)
public final class Ps01Client{
 private static BlockPos site;private static Direction facing;private static String reason="";private static long checked;private static Object world;
 private static boolean update(){var m=Minecraft.getInstance();if(m.level==null||m.player==null||m.screen!=null||!(m.player.getMainHandItem().getItem()instanceof Ps01Item)||!(m.hitResult instanceof BlockHitResult hit)||hit.getType()!=HitResult.Type.BLOCK||hit.getDirection()!=Direction.UP){site=null;return false;}var context=new BlockPlaceContext(m.player,net.minecraft.world.InteractionHand.MAIN_HAND,m.player.getMainHandItem(),hit);Direction face=Ps01Item.face(m.player,m.player.getMainHandItem());var root=Ps01Item.anchor(context.getClickedPos(),face);if(world!=m.level||!root.equals(site)||face!=facing||m.level.getGameTime()-checked>=5){world=m.level;site=root;facing=face;checked=m.level.getGameTime();reason=Ps01Item.check(m.level,root,face,m.player,m.player.getMainHandItem());}return true;}
 @SubscribeEvent public static void preview(RenderLevelStageEvent e){if(e.getStage()!=RenderLevelStageEvent.Stage.AFTER_TRANSLUCENT_BLOCKS||!update())return;var m=Minecraft.getInstance();var camera=e.getCamera().getPosition();var p=e.getPoseStack();var buffers=m.renderBuffers().bufferSource();p.pushPose();p.translate(site.getX()+.5-camera.x,site.getY()-camera.y,site.getZ()+.5-camera.z);p.mulPose(Axis.YP.rotationDegrees(-90*Ps01Geometry.quarter(facing)));Ps01Model.get().draw(p,buffers,0xf000f0,0xf000f0,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY,0,false,false,1,1,true,reason.isEmpty());p.popPose();p.pushPose();p.translate(-camera.x,-camera.y,-camera.z);var entry=Ps01Geometry.box(site,facing,new AABB(-1.2,.25,-4.28,0,2.67,-2.8));net.minecraft.client.renderer.LevelRenderer.renderLineBox(p,buffers.getBuffer(net.minecraft.client.renderer.RenderType.lines()),entry,1,.82f,.15f,.9f);p.popPose();buffers.endBatch();}
 @SubscribeEvent public static void hud(RenderGuiEvent.Post e){if(!update())return;var m=Minecraft.getInstance();String text="PS-01 | "+(reason.isEmpty()?"CLEAR — use to place":reason)+" | Sneak-use: rotate";e.getGuiGraphics().drawCenteredString(m.font,text,m.getWindow().getGuiScaledWidth()/2,m.getWindow().getGuiScaledHeight()-62,reason.isEmpty()?0xff85e3a4:0xffff8c85);}
}
